--
-- Name: publish_chat_message_change(); Type: FUNCTION; Schema: public; Owner: project_admin
--

CREATE FUNCTION public.publish_chat_message_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  row_data jsonb;
  target_conversation_id uuid;
begin
  if tg_op = 'DELETE' then
    row_data := to_jsonb(old);
    target_conversation_id := old.conversation_id;
  else
    row_data := to_jsonb(new);
    target_conversation_id := new.conversation_id;
  end if;
  perform realtime.publish('chat:' || target_conversation_id::text,
    case when tg_op = 'DELETE' then 'message_deleted' else 'message_updated' end,
    jsonb_build_object('operation', tg_op, 'record', row_data));
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION public.publish_chat_message_change() OWNER TO project_admin;

