--

CREATE VIEW public.public_blood_donors AS
 SELECT blood_donors.id,
    blood_donors.user_id,
    blood_donors.blood_group,
    blood_donors.availability,
    blood_donors.preferred_contact,
    blood_donors.donation_count,
    blood_donors.consent_listed,
    blood_donors.division_id,
    blood_donors.district_id,
    blood_donors.upazila_id,
    blood_donors.created_at,
    blood_donors.updated_at,
    blood_donors.phone,
    blood_donors.whatsapp
   FROM public.blood_donors
  WHERE ((blood_donors.consent_listed = true) AND (blood_donors.consent_contact = true) AND (blood_donors.consent_expiry >= now()) AND (blood_donors.archived_at IS NULL));


