c1d036a4-0af5-43c5-ac54-910d63953204	api-key	UPDATE_FUNCTION	FUNCTIONS	{"slug": "expire-blood-requests", "changes": {"code": "const corsHeaders = {\\r\\n  \\"Access-Control-Allow-Origin\\": \\"*\\",\\r\\n  \\"Access-Control-Allow-Methods\\": \\"POST, OPTIONS\\",\\r\\n  \\"Access-Control-Allow-Headers\\": \\"Authorization, Content-Type\\",\\r\\n};\\r\\n\\r\\nexport default async function (request: Request): Promise<Response> {\\r\\n  if (request.method === \\"OPTIONS\\") {\\r\\n    return new Response(null, { status: 204, headers: corsHeaders });\\r\\n  }\\r\\n\\r\\n  if (request.method !== \\"POST\\") {\\r\\n    return new Response(JSON.stringify({ error: \\"Method not allowed\\" }), {\\r\\n      status: 405,\\r\\n      headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n    });\\r\\n  }\\r\\n\\r\\n  const expectedToken = Deno.env.get(\\"BLOOD_REQUEST_EXPIRY_TOKEN\\");\\r\\n  if (!expectedToken) {\\r\\n    console.error(\\"Blood request expiry token is not configured.\\");\\r\\n    return new Response(JSON.stringify({ error: \\"Job is not configured\\" }), {\\r\\n      status: 500,\\r\\n      headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n    });\\r\\n  }\\r\\n\\r\\n  if (request.headers.get(\\"Authorization\\") !== `Bearer ${expectedToken}`) {\\r\\n    return new Response(JSON.stringify({ error: \\"Unauthorized\\" }), {\\r\\n      status: 401,\\r\\n      headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n    });\\r\\n  }\\r\\n\\r\\n  const baseUrl = Deno.env.get(\\"INSFORGE_BASE_URL\\");\\r\\n  const anonKey = Deno.env.get(\\"ANON_KEY\\");\\r\\n  if (!baseUrl || !anonKey) {\\r\\n    console.error(\\"Blood request expiry database connection is not configured.\\");\\r\\n    return new Response(JSON.stringify({ error: \\"Job is not configured\\" }), {\\r\\n      status: 500,\\r\\n      headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n    });\\r\\n  }\\r\\n\\r\\n  const response = await fetch(`${baseUrl.replace(/\\\\/$/, \\"\\")}/rest/v1/rpc/delete_expired_blood_requests`, {\\r\\n    method: \\"POST\\",\\r\\n    headers: {\\r\\n      apikey: anonKey,\\r\\n      Authorization: `Bearer ${anonKey}`,\\r\\n      \\"Content-Type\\": \\"application/json\\",\\r\\n      Accept: \\"application/json\\",\\r\\n    },\\r\\n    body: \\"{}\\",\\r\\n  });\\r\\n  if (!response.ok) {\\r\\n    console.error(\\"Could not delete expired blood requests:\\", response.status);\\r\\n    return new Response(JSON.stringify({ error: \\"Could not delete expired requests\\" }), {\\r\\n      status: 500,\\r\\n      headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n    });\\r\\n  }\\r\\n\\r\\n  const deletedCount = await response.json();\\r\\n  return new Response(JSON.stringify({ deletedCount: Number(deletedCount ?? 0) }), {\\r\\n    status: 200,\\r\\n    headers: { ...corsHeaders, \\"Content-Type\\": \\"application/json\\" },\\r\\n  });\\r\\n}\\r\\n", "name": "Expire blood requests", "description": "Permanently removes blood request rows after their Bangladesh-time expiry."}}	103.154.158.44	2026-10-23 11:35:07.310756+00	2026-10-23 11:35:07.310756+00
