20261021112947	add-insforge-auth-and-owned-records	{"create table if not exists public.profiles (\n  id uuid primary key references auth.users(id) on delete cascade,\n  username text not null unique,\n  full_name text not null,\n  email text not null,\n  phone text,\n  avatar text,\n  bio text,\n  division_id uuid,\n  district_id uuid,\n  upazila_id uuid,\n  role text not null default 'user' check (role in ('user', 'moderator', 'admin')),\n  status text not null default 'active' check (status in ('active', 'suspended', 'pending')),\n  email_verified boolean not null default false,\n  terms_accepted_at timestamptz,\n  blood_group text,\n  gender text,\n  date_of_birth date,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create index if not exists profiles_username_idx on public.profiles (username)","alter table public.profiles enable row level security","create or replace function public.is_current_user_staff()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = pg_catalog, public, pg_temp\nset row_security = off\nas $$\n  select exists (\n    select 1 from public.profiles\n    where id = auth.uid() and status = 'active' and role in ('admin', 'moderator')\n  );\n$$","create or replace function public.guard_profile_privileges()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, pg_temp\nset row_security = off\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    new.role := 'user';\n    new.status := 'active';\n    new.email_verified := coalesce((auth.jwt()->>'email_verified')::boolean, false);\n  elsif (new.role is distinct from old.role\n      or new.status is distinct from old.status\n      or new.email_verified is distinct from old.email_verified)\n      and not public.is_current_user_staff() then\n    raise exception 'Only staff can change protected account fields' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$","drop trigger if exists profiles_guard_privileges on public.profiles","create trigger profiles_guard_privileges\n  before insert or update on public.profiles\n  for each row execute function public.guard_profile_privileges()","drop policy if exists profiles_select_self on public.profiles","create policy profiles_select_self on public.profiles\n  for select to authenticated using (id = (select auth.uid()) or public.is_current_user_staff())","drop policy if exists profiles_insert_self on public.profiles","create policy profiles_insert_self on public.profiles\n  for insert to authenticated with check (id = (select auth.uid()))","drop policy if exists profiles_update_self on public.profiles","create policy profiles_update_self on public.profiles\n  for update to authenticated using (id = (select auth.uid()) or public.is_current_user_staff())\n  with check (id = (select auth.uid()) or public.is_current_user_staff())","revoke all on public.profiles from anon","revoke all on public.profiles from authenticated","grant select, insert on public.profiles to authenticated","grant update (username, full_name, phone, avatar, bio, division_id, district_id, upazila_id, terms_accepted_at, blood_group, gender, date_of_birth, updated_at, role, status, email_verified)\n  on public.profiles to authenticated","grant execute on function public.is_current_user_staff() to authenticated","create or replace view public.public_profiles as\n  select id, username, full_name, avatar, bio, division_id, district_id, upazila_id, created_at\n  from public.profiles","grant select on public.public_profiles to anon, authenticated","alter table public.sample_records\n  add column if not exists user_id uuid references auth.users(id) on delete cascade","create index if not exists sample_records_user_created_idx\n  on public.sample_records (user_id, created_at desc)","create or replace function public.set_sample_record_owner()\nreturns trigger\nlanguage plpgsql\nset search_path = pg_catalog, public, pg_temp\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    if auth.uid() is null then\n      raise exception 'Sign in is required to create a record' using errcode = '42501';\n    end if;\n    new.user_id := auth.uid();\n  elsif new.user_id is distinct from old.user_id then\n    raise exception 'Record ownership cannot be changed' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$","drop trigger if exists sample_records_set_owner on public.sample_records","create trigger sample_records_set_owner\n  before insert or update on public.sample_records\n  for each row execute function public.set_sample_record_owner()","alter table public.sample_records enable row level security","drop policy if exists sample_records_select_owner on public.sample_records","create policy sample_records_select_owner on public.sample_records\n  for select to authenticated using (user_id = (select auth.uid()))","drop policy if exists sample_records_insert_owner on public.sample_records","create policy sample_records_insert_owner on public.sample_records\n  for insert to authenticated with check (user_id = (select auth.uid()))","drop policy if exists sample_records_update_owner on public.sample_records","create policy sample_records_update_owner on public.sample_records\n  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))","drop policy if exists sample_records_delete_owner on public.sample_records","create policy sample_records_delete_owner on public.sample_records\n  for delete to authenticated using (user_id = (select auth.uid()))","revoke all on public.sample_records from anon","revoke all on public.sample_records from authenticated","grant select (id, user_id, title, category, description, created_at) on public.sample_records to authenticated","grant insert (title, category, description) on public.sample_records to authenticated","grant update (title, category, description) on public.sample_records to authenticated","grant delete on public.sample_records to authenticated"}	2026-10-21 11:31:52.289078+00
20261021113859	tighten-profile-and-admin-records	{"alter table public.profiles\n  add constraint profiles_username_format check (username ~ '^[a-z0-9_]{3,24}$'),\n  add constraint profiles_full_name_bounds check (length(btrim(full_name)) between 1 and 120)","create or replace function public.set_sample_record_owner()\nreturns trigger\nlanguage plpgsql\nset search_path = pg_catalog, public, pg_temp\nas $$\nbegin\n  if tg_op = 'INSERT' then\n    if auth.uid() is not null then\n      new.user_id := auth.uid();\n    elsif current_user = 'project_admin' and new.user_id is not null then\n      null;\n    else\n      raise exception 'Sign in is required to create a record' using errcode = '42501';\n    end if;\n  elsif new.user_id is distinct from old.user_id and current_user <> 'project_admin' then\n    raise exception 'Record ownership cannot be changed' using errcode = '42501';\n  end if;\n  return new;\nend;\n$$"}	2026-10-21 11:39:19.009557+00
