20261021183000	add-community-post-images	{"create table if not exists public.posts (\n  id uuid primary key default gen_random_uuid(),\n  author_id uuid not null references public.profiles(id) on delete cascade,\n  body text not null,\n  image text,\n  image_key text,\n  reactions integer not null default 0 check (reactions >= 0),\n  status text not null default 'visible'\n    check (status in ('visible', 'hidden', 'pending', 'deleted')),\n  division_id uuid,\n  district_id uuid,\n  upazila_id uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create index if not exists posts_status_created_idx\n  on public.posts (status, created_at desc)","create index if not exists posts_author_created_idx\n  on public.posts (author_id, created_at desc)","alter table public.posts enable row level security","revoke all on public.posts from anon, authenticated","grant select on public.posts to anon, authenticated","grant insert (author_id, body, image, image_key, reactions, status,\n  division_id, district_id, upazila_id) on public.posts to authenticated","grant update (body, image, image_key, reactions, status, division_id,\n  district_id, upazila_id, updated_at) on public.posts to authenticated","grant delete on public.posts to authenticated","drop policy if exists posts_public_read on public.posts","create policy posts_public_read on public.posts\n  for select to anon, authenticated using (status = 'visible')","drop policy if exists posts_moderation_read on public.posts","create policy posts_moderation_read on public.posts\n  for select to authenticated using (public.is_current_user_staff())","drop policy if exists posts_insert_owner on public.posts","create policy posts_insert_owner on public.posts\n  for insert to authenticated with check (author_id = (select auth.uid()))","drop policy if exists posts_update_owner_or_staff on public.posts","create policy posts_update_owner_or_staff on public.posts\n  for update to authenticated\n  using (author_id = (select auth.uid()) or public.is_current_user_staff())\n  with check (author_id = (select auth.uid()) or public.is_current_user_staff())","drop policy if exists posts_delete_owner_or_staff on public.posts","create policy posts_delete_owner_or_staff on public.posts\n  for delete to authenticated\n  using (author_id = (select auth.uid()) or public.is_current_user_staff())","alter table public.posts add column if not exists image_key text","drop policy if exists community_post_images_public_read on storage.objects","create policy community_post_images_public_read on storage.objects\n  for select to anon, authenticated\n  using (bucket = 'profile-images')","grant select on storage.objects to anon, authenticated","grant usage on schema storage to anon","drop policy if exists community_moderators_delete_post_images on storage.objects","create policy community_moderators_delete_post_images on storage.objects\n  for delete to authenticated\n  using (\n    bucket = 'profile-images'\n    and exists (\n      select 1 from public.profiles moderator\n      where moderator.id = auth.uid() and moderator.role in ('admin', 'moderator')\n    )\n    and exists (\n      select 1 from public.posts post\n      where post.image like '%' || replace(storage.objects.key, '/', '%2F')\n    )\n  )"}	2026-10-21 16:43:22.626622+00
