20261021185600	create-news	{"create table if not exists public.news (\n  id uuid primary key default gen_random_uuid(),\n  slug text not null unique,\n  title text not null,\n  excerpt text not null,\n  body text not null,\n  image text not null default '/images/news/user.svg',\n  category text not null check (category in ('national', 'district', 'health', 'education', 'sports', 'community')),\n  author_id uuid not null references public.profiles(id) on delete cascade,\n  source text,\n  status text not null default 'pending_review'\n    check (status in ('draft', 'pending_review', 'published', 'rejected', 'archived')),\n  published_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n)","create index if not exists news_status_published_idx\n  on public.news (status, published_at desc nulls last)","create index if not exists news_author_created_idx\n  on public.news (author_id, created_at desc)","alter table public.news enable row level security","revoke all on public.news from anon, authenticated","grant select on public.news to anon, authenticated","grant insert (slug, title, excerpt, body, image, category, author_id, source, status)\n  on public.news to authenticated","grant update (status, published_at, updated_at)\n  on public.news to authenticated","drop policy if exists news_public_read on public.news","create policy news_public_read on public.news\n  for select to anon, authenticated\n  using (status = 'published')","drop policy if exists news_author_read on public.news","create policy news_author_read on public.news\n  for select to authenticated\n  using (author_id = (select auth.uid()))","drop policy if exists news_staff_read on public.news","create policy news_staff_read on public.news\n  for select to authenticated\n  using (public.is_current_user_staff())","drop policy if exists news_author_insert_pending on public.news","create policy news_author_insert_pending on public.news\n  for insert to authenticated\n  with check (\n    author_id = (select auth.uid())\n    and status = 'pending_review'\n  )","drop policy if exists news_staff_update on public.news","create policy news_staff_update on public.news\n  for update to authenticated\n  using (public.is_current_user_staff())\n  with check (public.is_current_user_staff())","create or replace function public.set_news_published_at()\nreturns trigger\nlanguage plpgsql\nset search_path = pg_catalog, public, pg_temp\nas $$\nbegin\n  if new.status = 'published' and new.published_at is null then\n    new.published_at := now();\n  end if;\n  return new;\nend;\n$$","drop trigger if exists news_set_published_at on public.news","create trigger news_set_published_at\n  before insert or update of status, published_at on public.news\n  for each row execute function public.set_news_published_at()"}	2026-10-21 17:49:28.06942+00
