t null default 'unverified',\n  division_id text references public.divisions(id),\n  district_id text references public.districts(id),\n  upazila_id text references public.upazilas(id),\n  status text not null default 'published',\n  created_at timestamptz default now(), updated_at timestamptz default now()\n)","create table if not exists public.blood_donors (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.profiles(id) on delete cascade,\n  blood_group text not null, availability text not null default 'available',\n  preferred_contact text not null default 'phone', contact_value text not null,\n  phone text, whatsapp text, last_donation_at date, donation_count integer default 0,\n  notes text, consent_listed boolean default false, consent_contact boolean default false,\n  consent_expiry timestamptz not null,\n  division_id text references public.divisions(id),\n  district_id text references public.districts(id),\n  upazila_id text references public.upazilas(id),\n  created_at timestamptz default now(), updated_at timestamptz default now()\n)","create table if not exists public.blood_requests (\n  id uuid primary key default gen_random_uuid(),\n  requester_id uuid not null references public.profiles(id) on delete cascade,\n  blood_group text not null, units integer not null check (units between 1 and 20),\n  patient text, hospital text not null, needed_by date not null, notes text,\n  status text not null default 'under_review',\n  division_id text references public.divisions(id),\n  district_id text references public.districts(id),\n  upazila_id text references public.upazilas(id),\n  created_at timestamptz default now(), updated_at timestamptz default now()\n)","create or replace view public.public_blood_donors as\nselect id, user_id, blood_group, availability, preferred_contact, donation_count,\n       consent_listed, division_id, district_id, upazila_id, created_at, updated_at\nfrom public.blood_donors\nwhere consent_