20261021185950	create-connection-messaging-tables	{"create table if not exists public.connections (\n  id uuid primary key default gen_random_uuid(),\n  requester_id uuid not null references public.profiles(id) on delete cascade,\n  addressee_id uuid not null references public.profiles(id) on delete cascade,\n  status text not null default 'pending' check (status in ('pending', 'accepted', 'rejected', 'cancelled')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint connections_distinct_users check (requester_id <> addressee_id),\n  constraint connections_unique_pair unique (requester_id, addressee_id)\n)","create table if not exists public.conversations (\n  id uuid primary key default gen_random_uuid(),\n  participant_ids uuid[] not null,\n  conversation_type text not null default 'connection' check (conversation_type in ('connection', 'blood')),\n  blood_target_type text,\n  blood_target_id uuid,\n  updated_at timestamptz not null default now(),\n  constraint conversations_two_distinct_participants check (\n    cardinality(participant_ids) = 2 and participant_ids[1] <> participant_ids[2]\n  )\n)","create table if not exists public.messages (\n  id uuid primary key default gen_random_uuid(),\n  conversation_id uuid not null references public.conversations(id) on delete cascade,\n  sender_id uuid not null references public.profiles(id) on delete cascade,\n  body text not null default '',\n  read_by uuid[] not null default '{}',\n  attachment_key text,\n  attachment_mime_type text,\n  attachment_type text check (attachment_type in ('image', 'audio')),\n  created_at timestamptz not null default now(),\n  constraint messages_content_required check (length(btrim(body)) > 0 or attachment_key is not null),\n  constraint messages_attachment_metadata_complete check (\n    (attachment_key is null and attachment_mime_type is null and attachment_type is null)\n    or (attachment_key is not null and attachment_mime_type is not null and attachment_type is not null)\n  )\n)","create index if not exists connections_requester_status_idx on public.connections (requester_id, status, created_at desc)","create index if not exists connections_addressee_status_idx on public.connections (addressee_id, status, created_at desc)","create index if not exists conversations_participants_gin_idx on public.conversations using gin (participant_ids)","create unique index if not exists conversations_connection_pair_idx\n  on public.conversations (least(participant_ids[1], participant_ids[2]), greatest(participant_ids[1], participant_ids[2]))\n  where conversation_type = 'connection'","create unique index if not exists connections_pair_ordered_idx\n  on public.connections (least(requester_id, addressee_id), greatest(requester_id, addressee_id))","create index if not exists messages_conversation_created_idx on public.messages (conversation_id, created_at)","create index if not exists messages_attachment_key_idx on public.messages (attachment_key) where attachment_key is not null","alter table public.connections enable row level security","alter table public.conversations enable row level security","alter table public.messages enable row level security","grant select, insert, update, delete on public.connections to authenticated","grant select, insert, update on public.conversations to authenticated","grant select, insert, update on public.messages to authenticated","revoke all on public.connections, public.conversations, public.messages from anon","drop policy if exists connections_participant_read on public.connections","create policy connections_participant_read on public.connections for select to authenticated\n  using (auth.uid() = requester_id or auth.uid() = addressee_id)","drop policy if exists connections_requester_insert on public.connections","create policy connections_requester_insert on public.connections for insert to authenticated\n  with check (auth.uid() = requester_id and status = 'pending')","drop policy if exists connections_addressee_respond on public.connections","create policy connections_addressee_respond on public.connections for update to authenticated\n  using (auth.uid() = addressee_id and status = 'pending')\n  with check (auth.uid() = addressee_id and status in ('accepted', 'rejected'))","drop policy if exists connections_requester_cancel on public.connections","create policy connections_requester_cancel on public.connections for delete to authenticated\n  using (auth.uid() = requester_id and status = 'pending')","drop policy if exists conversations_participant_read on public.conversations","create policy conversations_participant_read on public.conversations for select to authenticated\n  using (auth.uid() = any(participant_ids))","drop policy if exists conversations_insert_allowed on public.conversations","create policy conversations_insert_allowed on public.conversations for insert to authenticated\n  with check (\n    auth.uid() = any(participant_ids) and cardinality(participant_ids) = 2\n    and conversation_type = 'connection'\n    and exists (\n      select 1 from public.connections edge\n      where edge.status = 'accepted'\n        and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(participant_ids, auth.uid())))\n          or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(participant_ids, auth.uid())))\n        )\n    )\n  )","drop policy if exists messages_read_own on public.messages","create policy messages_read_own on public.messages for select to authenticated using (\n  exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and auth.uid() = any(c.participant_ids)\n      and (c.conversation_type = 'blood' or exists (\n        select 1 from public.connections edge where edge.status = 'accepted'\n          and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n            or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n          )\n      ))\n  )\n)","drop policy if exists messages_insert_auth on public.messages","create policy messages_insert_auth on public.messages for insert to authenticated with check (\n  auth.uid() = sender_id and exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and auth.uid() = any(c.participant_ids)\n      and (c.conversation_type = 'blood' or exists (\n        select 1 from public.connections edge where edge.status = 'accepted'\n          and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n            or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n          )\n      ))\n  )\n)","alter table storage.objects enable row level security","grant select, insert, delete on storage.objects to authenticated","drop policy if exists chat_media_participant_read on storage.objects","create policy chat_media_participant_read on storage.objects for select to authenticated\n  using (\n    bucket = 'chat-media'\n    and exists (\n      select 1 from public.messages m\n      join public.conversations c on c.id = m.conversation_id\n      where m.attachment_key = storage.objects.key\n        and auth.uid() = any(c.participant_ids)\n        and (c.conversation_type = 'blood' or exists (\n          select 1 from public.connections edge\n          where edge.status = 'accepted'\n            and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n              or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n            )\n        ))\n    )\n  )","drop policy if exists chat_media_sender_upload on storage.objects","create policy chat_media_sender_upload on storage.objects for insert to authenticated\n  with check (\n    bucket = 'chat-media'\n    and (storage.foldername(key))[1] = (select auth.jwt() ->> 'sub')\n    and (storage.foldername(key))[2] ~ '^[0-9a-fA-F-]{36}$'\n    and storage.filename(key) ~* '\\\\.(jpe?g|png|webp|webm|mp4|m4a|mp3|ogg|wav|aac)$'\n    and exists (\n      select 1 from public.conversations c\n      where c.id = (storage.foldername(key))[2]::uuid\n        and auth.uid() = any(c.participant_ids)\n        and (c.conversation_type = 'blood' or exists (\n          select 1 from public.connections edge\n          where edge.status = 'accepted'\n            and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n              or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n            )\n        ))\n    )\n  )","drop policy if exists chat_media_sender_delete on storage.objects","create policy chat_media_sender_delete on storage.objects for delete to authenticated\n  using (bucket = 'chat-media' and (storage.foldername(key))[1] = (select auth.jwt() ->> 'sub'))","create or replace function public.publish_chat_message()\nreturns trigger language plpgsql security definer set search_path = public, pg_temp\nas $$\nbegin\n  perform realtime.publish('chat:' || new.conversation_id::text, 'new_message', jsonb_build_object(\n    'id', new.id, 'conversation_id', new.conversation_id, 'sender_id', new.sender_id,\n    'body', new.body, 'attachment_key', new.attachment_key,\n    'attachment_mime_type', new.attachment_mime_type, 'attachment_type', new.attachment_type,\n    'created_at', new.created_at\n  ));\n  return new;\nend;\n$$","drop trigger if exists publish_chat_message_after_insert on public.messages","create trigger publish_chat_message_after_insert after insert on public.messages\n  for each row execute function public.publish_chat_message()"}	2026-10-21 18:58:12.292403+00
