      )\n    )\n  )","drop policy if exists messages_read_own on public.messages","create policy messages_read_own on public.messages for select to authenticated using (\n  exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id\n      and auth.uid() = any(c.participant_ids)\n      and (\n        c.conversation_type = 'blood'\n        or exists (\n          select 1 from public.connections edge\n          where edge.status = 'accepted'\n            and (\n              (edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n              or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n            )\n        )\n      )\n  )\n)","drop policy if exists messages_insert_auth on public.messages","create policy messages_insert_auth on public.messages for insert to authenticated with check (\n  auth.uid() = sender_id\n  and exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id\n      and auth.uid() = any(c.participant_ids)\n      and (\n        c.conversation_type = 'blood'\n        or exists (\n          select 1 from public.connections edge\n          where edge.status = 'accepted'\n            and (\n              (edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n              or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n            )\n        )\n      )\n  )\n)","insert into realtime.channels (pattern, description, enabled)\nvalues ('chat:%', 'Private chat events for conversation participants', true)\non conflict (pattern) do update\nset description = excluded.description, enabled = excluded.enabled","alter table realtime.channels enable row level security","drop policy if exists chat_participants_subscribe on realtime.channels","create policy chat_participants_subscribe on realtime.channels\n  for select to authenticated\n  using (\n    pattern = 'chat:%'\n    and exists (\n      select 1 from public.conversations c\n      where c.id = nullif(split_part(realtime.channel_name(), ':', 2), '')::uuid\n        and auth.uid() = any(c.participant_ids)\n        and (\n          c.conversation_type = 'blood'\n          or exists (\n            select 1 from public.connections edge\n            where edge.status = 'accepted'\n              and (\n                (edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n                or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n              )\n          )\n        )\n    )\n  )","create or replace function public.publish_chat_message()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  perform realtime.publish(\n    'chat:' || new.conversation_id::text,\n    'new_message',\n    jsonb_build_object(\n      'id', new.id,\n      'conversation_id', new.conversation_id,\n      'sender_id', new.sender_id,\n      'body', new.body,\n      'created_at', new.created_at\n    )\n  );\n  return new;\nend;\n$$","drop trigger if exists publish_chat_message_after_insert on public.messages","create trigger publish_chat_message_after_insert\n  after insert on public.messages\n  for each row execute function public.publish_chat_message()"}	2026-10-21 18:58:12.691286+00
