20261022120000	secure-admin-user-deletion	{"create or replace function public.admin_delete_user(target_user_id uuid)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, auth, pg_temp\nas $$\ndeclare\n  requester_role text;\n  target_role text;\n  deleted_count integer;\nbegin\n  select role into requester_role from public.profiles where id = auth.uid();\n  if requester_role is distinct from 'admin' then\n    raise exception 'Only administrators can delete accounts' using errcode = '42501';\n  end if;\n  select role into target_role from public.profiles where id = target_user_id;\n  if target_role is null then return false; end if;\n  if target_role = 'admin' then\n    raise exception 'Administrator accounts cannot be deleted through this action' using errcode = '42501';\n  end if;\n  delete from auth.users where id = target_user_id;\n  get diagnostics deleted_count = row_count;\n  return deleted_count > 0;\nend;\n$$","revoke all on function public.admin_delete_user(uuid) from public, anon","grant execute on function public.admin_delete_user(uuid) to authenticated"}	2026-10-22 09:39:47.152559+00
