20261022130001	message-unread-state	{"create or replace function public.get_unread_message_counts()\nreturns table (conversation_id uuid, unread_count bigint)\nlanguage sql\nstable\nsecurity definer\nset search_path = pg_catalog, public, auth, pg_temp\nas $$\n  select c.id, count(m.id)\n  from public.conversations c\n  join public.connections edge\n    on edge.status = 'accepted'\n   and (\n     (edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n     or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))\n   )\n  left join public.messages m\n    on m.conversation_id = c.id\n   and m.sender_id <> auth.uid()\n   and not (auth.uid() = any(m.read_by))\n  where auth.uid() is not null\n    and c.conversation_type = 'connection'\n    and auth.uid() = any(c.participant_ids)\n  group by c.id;\n$$","create or replace function public.mark_conversation_messages_read(target_conversation_id uuid)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, auth, pg_temp\nas $$\ndeclare\n  current_user_id uuid := auth.uid();\n  affected_count integer;\nbegin\n  if current_user_id is null or not exists (\n    select 1\n    from public.conversations c\n    join public.connections edge\n      on edge.status = 'accepted'\n     and (\n       (edge.requester_id = current_user_id and edge.addressee_id = any(array_remove(c.participant_ids, current_user_id)))\n       or (edge.addressee_id = current_user_id and edge.requester_id = any(array_remove(c.participant_ids, current_user_id)))\n     )\n    where c.id = target_conversation_id\n      and c.conversation_type = 'connection'\n      and current_user_id = any(c.participant_ids)\n  ) then\n    raise exception 'Conversation is unavailable' using errcode = '42501';\n  end if;\n\n  update public.messages m\n     set read_by = array_append(m.read_by, current_user_id)\n   where m.conversation_id = target_conversation_id\n     and m.sender_id <> current_user_id\n     and not (current_user_id = any(m.read_by));\n  get diagnostics affected_count = row_count;\n  return affected_count;\nend;\n$$","revoke all on function public.get_unread_message_counts() from public, anon","revoke all on function public.mark_conversation_messages_read(uuid) from public, anon","grant execute on function public.get_unread_message_counts() to authenticated","grant execute on function public.mark_conversation_messages_read(uuid) to authenticated"}	2026-10-22 11:10:46.811135+00
20261022140000	chat-message-controls	{"alter table public.messages\n  add column if not exists delivered_to uuid[] not null default '{}',\n  add column if not exists edited_at timestamptz","revoke update on public.messages from authenticated","grant update (body, edited_at) on public.messages to authenticated","grant delete on public.messages to authenticated","drop policy if exists messages_sender_edit_own on public.messages","create policy messages_sender_edit_own on public.messages for update to authenticated\n  using (sender_id = auth.uid() and exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and auth.uid() = any(c.participant_ids)\n      and c.conversation_type = 'connection'\n      and exists (select 1 from public.connections edge where edge.status = 'accepted'\n        and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n          or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))))\n  ))\n  with check (sender_id = auth.uid() and exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and auth.uid() = any(c.participant_ids)\n      and c.conversation_type = 'connection'\n      and exists (select 1 from public.connections edge where edge.status = 'accepted'\n        and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n          or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))))\n  ))","drop policy if exists messages_sender_delete_own on public.messages","create policy messages_sender_delete_own on public.messages for delete to authenticated\n  using (sender_id = auth.uid() and exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and auth.uid() = any(c.participant_ids)\n      and c.conversation_type = 'connection'\n      and exists (select 1 from public.connections edge where edge.status = 'accepted'\n        and ((edge.requester_id = auth.uid() and edge.addressee_id = any(array_remove(c.participant_ids, auth.uid())))\n          or (edge.addressee_id = auth.uid() and edge.requester_id = any(array_remove(c.participant_ids, auth.uid())))))\n  ))","create or replace function public.mark_conversation_messages_delivered(target_conversation_id uuid)\nreturns integer\nlanguage plpgsql security definer\nset search_path = pg_catalog, public, auth, pg_temp\nas $$\ndeclare\n  current_user_id uuid := auth.uid();\n  affected_count integer;\nbegin\n  if current_user_id is null or not exists (\n    select 1 from public.conversations c\n    join public.connections edge on edge.status = 'accepted'\n      and ((edge.requester_id = current_user_id and edge.addressee_id = any(array_remove(c.participant_ids, current_user_id)))\n        or (edge.addressee_id = current_user_id and edge.requester_id = any(array_remove(c.participant_ids, current_user_id))))\n    where c.id = target_conversation_id and c.conversation_type = 'connection'\n      and current_user_id = any(c.participant_ids)\n  ) then\n    raise exception 'Conversation is unavailable' using errcode = '42501';\n  end if;\n  update public.messages m\n    set delivered_to = array_append(m.delivered_to, current_user_id)\n    where m.conversation_id = target_conversation_id and m.sender_id <> current_user_id\n      and not (current_user_id = any(m.delivered_to));\n  get diagnostics affected_count = row_count;\n  return affected_count;\nend;\n$$","revoke all on function public.mark_conversation_messages_delivered(uuid) from public, anon","grant execute on function public.mark_conversation_messages_delivered(uuid) to authenticated","create or replace function public.publish_chat_message_change()\nreturns trigger language plpgsql security definer set search_path = public, pg_temp\nas $$\ndeclare\n  row_data jsonb;\n  target_conversation_id uuid;\nbegin\n  if tg_op = 'DELETE' then\n    row_data := to_jsonb(old);\n    target_conversation_id := old.conversation_id;\n  else\n    row_data := to_jsonb(new);\n    target_conversation_id := new.conversation_id;\n  end if;\n  perform realtime.publish('chat:' || target_conversation_id::text,\n    case when tg_op = 'DELETE' then 'message_deleted' else 'message_updated' end,\n    jsonb_build_object('operation', tg_op, 'record', row_data));\n  if tg_op = 'DELETE' then return old; end if;\n  return new;\nend;\n$$","drop trigger if exists publish_chat_message_change on public.messages","create trigger publish_chat_message_change after update or delete on public.messages\n  for each row execute function public.publish_chat_message_change()"}	2026-10-22 11:30:59.587046+00
20261022153000	message-replies-reactions	{"alter table public.messages\n  add column if not exists reply_to_message_id uuid references public.messages(id) on delete set null,\n  add column if not exists reactions jsonb not null default '[]'::jsonb","create index if not exists messages_reply_to_message_id_idx\n  on public.messages (reply_to_message_id)\n  where reply_to_message_id is not null","create or replace function public.toggle_message_reaction(target_message_id uuid, target_emoji text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, auth, pg_temp\nas $$\ndeclare\n  current_user_id uuid := auth.uid();\n  target_conversation_id uuid;\n  current_reactions jsonb;\n  has_reaction boolean;\n  next_reactions jsonb;\nbegin\n  if current_user_id is null then\n    raise exception 'Authentication required' using errcode = '42501';\n  end if;\n  if target_emoji not in ('👍', '❤️', '😂', '😮', '😢', '🙏') then\n    raise exception 'Unsupported reaction' using errcode = '22023';\n  end if;\n\n  select m.conversation_id, coalesce(m.reactions, '[]'::jsonb)\n    into target_conversation_id, current_reactions\n    from public.messages m\n    where m.id = target_message_id\n    for update;\n\n  if target_conversation_id is null or not exists (\n    select 1\n    from public.conversations c\n    join public.connections edge on edge.status = 'accepted'\n      and ((edge.requester_id = current_user_id and edge.addressee_id = any(array_remove(c.participant_ids, current_user_id)))\n        or (edge.addressee_id = current_user_id and edge.requester_id = any(array_remove(c.participant_ids, current_user_id))))\n    where c.id = target_conversation_id\n      and c.conversation_type = 'connection'\n      and current_user_id = any(c.participant_ids)\n  ) then\n    raise exception 'Message is unavailable' using errcode = '42501';\n  end if;\n\n  has_reaction := exists (\n    select 1 from jsonb_array_elements(current_reactions) reaction\n    where reaction->>'userId' = current_user_id::text and reaction->>'emoji' = target_emoji\n  );\n\n  select coalesce(jsonb_agg(reaction), '[]'::jsonb)\n    into next_reactions\n    from jsonb_array_elements(current_reactions) reaction\n    where not (reaction->>'userId' = current_user_id::text and reaction->>'emoji' = target_emoji);\n\n  if not has_reaction then\n    next_reactions := next_reactions || jsonb_build_array(jsonb_build_object('userId', current_user_id, 'emoji', target_emoji));\n  end if;\n\n  update public.messages set reactions = next_reactions where id = target_message_id;\n  return next_reactions;\nend;\n$$","revoke all on function public.toggle_message_reaction(uuid, text) from public, anon","grant execute on function public.toggle_message_reaction(uuid, text) to authenticated"}	2026-10-22 12:14:51.224134+00
20261023101318	chat-media-upload-identity-policy	{"ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY","GRANT USAGE ON SCHEMA storage TO authenticated","GRANT SELECT, INSERT, DELETE ON storage.objects TO authenticated","DROP POLICY IF EXISTS chat_media_sender_upload ON storage.objects","CREATE POLICY chat_media_sender_upload ON storage.objects\r\n  FOR INSERT TO authenticated\r\n  WITH CHECK (\r\n    bucket = 'chat-media'\r\n    AND (storage.foldername(key))[1] = (SELECT auth.uid()::text)\r\n    AND (storage.foldername(key))[2] ~ '^[0-9a-fA-F-]{36}$'\r\n    AND storage.filename(key) ~* '\\\\.(jpe?g|png|webp|webm|mp4|m4a|mp3|ogg|wav|aac)$'\r\n    AND EXISTS (\r\n      SELECT 1\r\n      FROM public.conversations c\r\n      WHERE c.id = (storage.foldername(key))[2]::uuid\r\n        AND auth.uid() = ANY(c.participant_ids)\r\n        AND (\r\n          c.conversation_type = 'blood'\r\n          OR EXISTS (\r\n            SELECT 1\r\n            FROM public.connections edge\r\n            WHERE edge.status = 'accepted'\r\n              AND (\r\n                (edge.requester_id = auth.uid() AND edge.addressee_id = ANY(array_remove(c.participant_ids, auth.uid())))\r\n                OR (edge.addressee_id = auth.uid() AND edge.requester_id = ANY(array_remove(c.participant_ids, auth.uid())))\r\n              )\r\n          )\r\n        )\r\n    )\r\n  )","DROP POLICY IF EXISTS chat_media_sender_delete ON storage.objects","CREATE POLICY chat_media_sender_delete ON storage.objects\r\n  FOR DELETE TO authenticated\r\n  USING (\r\n    bucket = 'chat-media'\r\n    AND (storage.foldername(key))[1] = (SELECT auth.uid()::text)\r\n  )"}	2026-10-23 10:13:42.226539+00
20261023102326	chat-media-upload-policy-helper	{"CREATE OR REPLACE FUNCTION public.can_upload_chat_media(target_conversation_id uuid)\r\nRETURNS boolean\r\nLANGUAGE sql\r\nSTABLE\r\nSECURITY DEFINER\r\nSET search_path = public, pg_temp\r\nAS $$\r\n  SELECT EXISTS (\r\n    SELECT 1\r\n    FROM public.conversations c\r\n    WHERE c.id = target_conversation_id\r\n      AND auth.uid() = ANY(c.participant_ids)\r\n      AND (\r\n        c.conversation_type = 'blood'\r\n        OR EXISTS (\r\n          SELECT 1\r\n          FROM public.connections edge\r\n          WHERE edge.status = 'accepted'\r\n            AND (\r\n              (edge.requester_id = auth.uid() AND edge.addressee_id = ANY(array_remove(c.participant_ids, auth.uid())))\r\n              OR (edge.addressee_id = auth.uid() AND edge.requester_id = ANY(array_remove(c.participant_ids, auth.uid())))\r\n            )\r\n        )\r\n      )\r\n  );\r\n$$","REVOKE ALL ON FUNCTION public.can_upload_chat_media(uuid) FROM PUBLIC, anon","GRANT EXECUTE ON FUNCTION public.can_upload_chat_media(uuid) TO authenticated","DROP POLICY IF EXISTS chat_media_sender_upload ON storage.objects","CREATE POLICY chat_media_sender_upload ON storage.objects\r\n  FOR INSERT TO authenticated\r\n  WITH CHECK (\r\n    bucket = 'chat-media'\r\n    AND (storage.foldername(key))[1] = (SELECT auth.uid()::text)\r\n    AND (storage.foldername(key))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\r\n    AND storage.filename(key) ~* '\\\\.(jpe?g|png|webp|webm|mp4|m4a|mp3|ogg|wav|aac)$'\r\n    AND public.can_upload_chat_media((storage.foldername(key))[2]::uuid)\r\n  )"}	2026-10-23 10:23:51.812444+00
