--
-- Name: conversations; Type: ROW SECURITY; Schema: public; Owner: project_admin
--

ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;

--
-- Name: conversations conversations_insert_allowed; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY conversations_insert_allowed ON public.conversations FOR INSERT TO authenticated WITH CHECK (((auth.uid() = ANY (participant_ids)) AND (cardinality(participant_ids) = 2) AND (((conversation_type = 'connection'::text) AND (EXISTS ( SELECT 1
   FROM public.connections edge
  WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(conversations.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(conversations.participant_ids, auth.uid()))))))))) OR ((conversation_type = 'blood'::text) AND (blood_target_id IS NOT NULL) AND (((blood_target_type = 'donor'::text) AND (EXISTS ( SELECT 1
   FROM public.public_blood_donors donor
  WHERE ((donor.id = conversations.blood_target_id) AND (donor.user_id = ANY (array_remove(conversations.participant_ids, auth.uid()))))))) OR ((blood_target_type = 'request'::text) AND (EXISTS ( SELECT 1
   FROM public.blood_requests request
  WHERE ((request.id = conversations.blood_target_id) AND (request.status = 'active'::text) AND (request.requester_id = ANY (array_remove(conversations.participant_ids, auth.uid()))))))))))));


--
-- Name: conversations conversations_participant_read; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY conversations_participant_read ON public.conversations FOR SELECT TO authenticated USING ((auth.uid() = ANY (participant_ids)));


