--
-- Name: messages; Type: ROW SECURITY; Schema: public; Owner: project_admin
--

ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;

--
-- Name: messages messages_insert_auth; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY messages_insert_auth ON public.messages FOR INSERT TO authenticated WITH CHECK (((auth.uid() = sender_id) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = messages.conversation_id) AND (auth.uid() = ANY (c.participant_ids)) AND ((c.conversation_type = 'blood'::text) OR (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))));


--
-- Name: messages messages_read_own; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY messages_read_own ON public.messages FOR SELECT TO authenticated USING (((NOT (auth.uid() = ANY (deleted_for))) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = messages.conversation_id) AND (auth.uid() = ANY (c.participant_ids)) AND ((c.conversation_type = 'blood'::text) OR (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))));


--
-- Name: messages messages_sender_delete_own; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY messages_sender_delete_own ON public.messages FOR DELETE TO authenticated USING (((sender_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = messages.conversation_id) AND (auth.uid() = ANY (c.participant_ids)) AND (c.conversation_type = 'connection'::text) AND (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid())))))))))))));


--
-- Name: messages messages_sender_edit_own; Type: POLICY; Schema: public; Owner: project_admin
--

CREATE POLICY messages_sender_edit_own ON public.messages FOR UPDATE TO authenticated USING (((sender_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = messages.conversation_id) AND (auth.uid() = ANY (c.participant_ids)) AND (c.conversation_type = 'connection'::text) AND (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))) WITH CHECK (((sender_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = messages.conversation_id) AND (auth.uid() = ANY (c.participant_ids)) AND (c.conversation_type = 'connection'::text) AND (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid())))))))))))));


