--
-- Name: channels; Type: ROW SECURITY; Schema: realtime; Owner: postgres
--

ALTER TABLE realtime.channels ENABLE ROW LEVEL SECURITY;

--
-- Name: channels chat_participants_subscribe; Type: POLICY; Schema: realtime; Owner: postgres
--

CREATE POLICY chat_participants_subscribe ON realtime.channels FOR SELECT TO authenticated USING (((pattern = 'chat:%'::text) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = (NULLIF(split_part(realtime.channel_name(), ':'::text, 2), ''::text))::uuid) AND (auth.uid() = ANY (c.participant_ids)) AND ((c.conversation_type = 'blood'::text) OR (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))));


--
-- Name: objects chat_media_participant_read; Type: POLICY; Schema: storage; Owner: postgres
--

CREATE POLICY chat_media_participant_read ON storage.objects FOR SELECT TO authenticated USING (((bucket = 'chat-media'::text) AND (EXISTS ( SELECT 1
   FROM (public.messages m
     JOIN public.conversations c ON ((c.id = m.conversation_id)))
  WHERE ((m.attachment_key = objects.key) AND (auth.uid() = ANY (c.participant_ids)) AND ((c.conversation_type = 'blood'::text) OR (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))));


--
-- Name: objects chat_media_sender_delete; Type: POLICY; Schema: storage; Owner: postgres
--

CREATE POLICY chat_media_sender_delete ON storage.objects FOR DELETE TO authenticated USING (((bucket = 'chat-media'::text) AND ((storage.foldername(key))[1] = ( SELECT (auth.uid())::text AS uid))));


--
-- Name: objects chat_media_sender_upload; Type: POLICY; Schema: storage; Owner: postgres
--

CREATE POLICY chat_media_sender_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket = 'chat-media'::text) AND ((storage.foldername(key))[1] = ( SELECT (auth.uid())::text AS uid)) AND ((storage.foldername(key))[2] ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text) AND (storage.filename(key) ~* '\.(jpe?g|png|webp|webm|mp4|m4a|mp3|ogg|wav|aac)$'::text) AND (EXISTS ( SELECT 1
   FROM public.conversations c
  WHERE ((c.id = ((storage.foldername(objects.key))[2])::uuid) AND (auth.uid() = ANY (c.participant_ids)) AND ((c.conversation_type = 'blood'::text) OR (EXISTS ( SELECT 1
           FROM public.connections edge
          WHERE ((edge.status = 'accepted'::text) AND (((edge.requester_id = auth.uid()) AND (edge.addressee_id = ANY (array_remove(c.participant_ids, auth.uid())))) OR ((edge.addressee_id = auth.uid()) AND (edge.requester_id = ANY (array_remove(c.participant_ids, auth.uid()))))))))))))));


